create table if not exists "sync_ops" ("user_id" text not null, "terminal_uuid" text not null, "op_id" text not null, "collection" text not null check (collection in ('itemStore', 'favouriteCard', 'favouriteItem', 'history', 'recentView', 'subscribe', 'config')), "entity_id" text not null, "action" text not null check (action in ('upsert', 'delete')), "data_hash" text not null, "base_version" text, "result" text not null check (result in ('applied', 'replayed', 'ignored_stale', 'conflict', 'failed')), "server_seq" integer, "entity_version" text, "error_code" text, "error_message" text, "received_at" integer not null, constraint "pk_sync_ops" primary key ("user_id", "terminal_uuid", "op_id"));
create index if not exists "idx_sync_ops_user_received" on "sync_ops" ("user_id", "received_at" desc)
